import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.1lR7qgqY.js";const k=JSON.parse('{"title":"K3 硬體選購","description":"","frontmatter":{},"headers":[],"relativePath":"know/k3-hardware.md","filePath":"know/k3-hardware.md","lastUpdated":1793014002000}'),o={name:"know/k3-hardware.md"};function l(i,t,n,h,s,c){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="k3-硬體選購" tabindex="-1">K3 硬體選購 <a class="header-anchor" href="#k3-硬體選購" aria-label="Permalink to &quot;K3 硬體選購&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 等級 E, F 的規格門檻尚未定義; 各等級可跑的模型大小為依 K2 公式的估算, 未實測; 價格見<a href="/docs-handbook-poc/ref/hardware-prices">硬體價格頁</a>, 本章不寫價格</li></ul></div><p><strong>結論</strong>: 預算有限時, 先買「更大的顯示記憶體 (或統一記憶體)」, 再考慮運算速度. 記憶體決定能不能跑, 運算速度只決定跑得多快 (信心: 高).</p><h2 id="k3-1-等級-a-至-f-的能力邊界" tabindex="-1">K3.1 等級 A 至 F 的能力邊界 <a class="header-anchor" href="#k3-1-等級-a-至-f-的能力邊界" aria-label="Permalink to &quot;K3.1 等級 A 至 F 的能力邊界&quot;">​</a></h2><p>下表依 <a href="/docs-handbook-poc/know/k2-quantization">K2</a>的公式估算 4 位元量化模型的大致落點. 結果為推論 (信心: 中), 未實測; 實際能否執行, 還取決於上下文長度與同時使用人數.</p><table tabindex="0"><thead><tr><th>等級</th><th>記憶體條件</th><th>較可能的落點 (4 位元量化, 推論)</th><th>建議架構</th></tr></thead><tbody><tr><td>A</td><td>無獨立顯示卡, 以系統記憶體運算</td><td>數十億參數以下的小模型, 速度較慢</td><td><a href="/docs-handbook-poc/build/overview">最小組合</a></td></tr><tr><td>B</td><td>8 至 12GB 顯示記憶體</td><td>約 8B 級模型餘裕較大; 約 14B 級須壓低上下文</td><td>最小組合</td></tr><tr><td>C</td><td>Apple Silicon, 統一記憶體</td><td>依記憶體容量而定, 16GB 與 32GB 以上差異大</td><td>16GB 用最小組合; 32GB 以上可用標準組合</td></tr><tr><td>D</td><td>16GB 顯示記憶體</td><td>約 14B 級餘裕較大; 約 30B 以上通常放不下</td><td>標準組合</td></tr><tr><td>E</td><td>待 K3 補充門檻</td><td>同 D, 並有餘裕同時載入嵌入模型</td><td>標準組合</td></tr><tr><td>F</td><td>待 K3 補充門檻</td><td>較大的模型或多人同時使用</td><td>進階組合 (須有人每週維運)</td></tr></tbody></table><h2 id="k3-2-記憶體優先的選購順序" tabindex="-1">K3.2 記憶體優先的選購順序 <a class="header-anchor" href="#k3-2-記憶體優先的選購順序" aria-label="Permalink to &quot;K3.2 記憶體優先的選購順序&quot;">​</a></h2><ol><li><strong>容量</strong>: 先確認想跑的模型加 KV cache 放得進去 (K2).</li><li><strong>記憶體頻寬</strong>: 產生文字的速度常受記憶體頻寬限制, 而非純運算能力 (信心: 中高, 屬一般經驗).</li><li><strong>驅動與軟體支援</strong>: Ollama 的 NVIDIA 支援要求運算能力 (compute capability) 5.0 以上, 驅動版本 550 以上; 運算能力 5.0 至 6.2 的舊卡須驅動 570 以上 (來源: Ollama 文件 GPU). AMD 與 Apple 的支援見 <a href="/docs-handbook-poc/build/m1-inference">M1.4 節</a>.</li><li><strong>電源, 散熱與機殼空間</strong>: 高階顯示卡對電源供應器與機殼有要求, 購買前核對規格書 (信心: 高, 屬一般經驗).</li><li><strong>價格時機</strong>: DRAM 與 GPU 價格波動大, 以<a href="/docs-handbook-poc/ref/hardware-prices">價格頁</a>的查價日期為準, 不憑舊資料決定.</li></ol><p>升級既有電腦與另購整機之間, 差異主要在顯示記憶體能否增加. 若現有機器的主機板, 電源與機殼都能容納較大的顯示卡, 升級通常較省 (信心: 低, 屬推論).</p><h2 id="k3-3-台灣通路與二手風險" tabindex="-1">K3.3 台灣通路與二手風險 <a class="header-anchor" href="#k3-3-台灣通路與二手風險" aria-label="Permalink to &quot;K3.3 台灣通路與二手風險&quot;">​</a></h2><p>價格與通路資訊放在<a href="/docs-handbook-poc/ref/hardware-prices">硬體價格頁</a>, 每筆須有來源與查價日期, 目前該頁尚無內容.</p><p>購買二手顯示卡時, 建議逐項檢查 (信心: 中, 屬一般經驗):</p><ul><li>[ ] 收到後立即用 <code>nvidia-smi</code> 確認型號與顯示記憶體容量與賣方標示相符.</li><li>[ ] 連續跑一段時間的推論或壓力測試, 觀察溫度與是否降頻或當機.</li><li>[ ] 確認保固剩餘期間與可否退換.</li><li>[ ] 確認驅動仍在支援清單內 (見上述 Ollama GPU 支援條件).</li><li>[ ] 外觀與風扇狀況, 是否有拆修痕跡.</li><li>[ ] 避免來源不明且價格明顯低於市場的商品.</li></ul><h2 id="研究-1-的分級依據" tabindex="-1">研究 1 的分級依據 <a class="header-anchor" href="#研究-1-的分級依據" aria-label="Permalink to &quot;研究 1 的分級依據&quot;">​</a></h2><p>等級定義來自研究 1 (待以第一手報價核對): A 無獨顯筆電; B 8 至 12GB 顯示記憶體的遊戲電腦; C Apple Silicon Mac; D 16GB 顯示卡升級; E, F 依預算區分. 預算區間見價格頁.</p>',15)])])}const b=a(o,[["render",l]]);export{k as __pageData,b as default};
